$ec_lang['cs_notes_1_term']='Metode';
$ec_lang['cs_notes_1_def']='Metode debit masuk-keluar memperkirakan rembesan dengan mengukur debit di ujung hulu dan hilir segmen saluran: Q<sub>loss</sub> = Q<sub>in</sub> &minus; Q<sub>out</sub>. Efisiensi saluran E<sub>c</sub> = Q<sub>out</sub> / Q<sub>in</sub>. Volume tahunan mengasumsikan operasi debit penuh terus-menerus; kehilangan aktual lebih rendah untuk saluran musiman atau aliran sebagian.';
